import math

def check_condition(n):
    if n < 0:
        return False

    denominator = 2 * n - 1
    if denominator == 0: # Should not happen for integer n
        return False

    try:
        numerator = 3 * (math.factorial(n + 2) + 1)
        if numerator % denominator == 0:
            return True
        else:
            return False
    except OverflowError:
        # For very large n, factorial might overflow standard float/int types, 
        # but for n up to 10, standard integers are fine.
        return False

# Test n from 0 to 10
solutions_up_to_10 = []
for n in range(11):
    if check_condition(n):
        solutions_up_to_10.append(n)

print(f"Solutions found for n in [0, 10]: {solutions_up_to_10}")

import math

def calculate_E(n):
    # E(n) = 3 * ((n+2)! + 1) / (2n - 1)
    numerator = 3 * (math.factorial(n + 2) + 1)
    denominator = 2 * n - 1

    if denominator == 0:
        return "Undefined (n=0.5)", None

    # Check if the division results in an integer
    if numerator % denominator == 0:
        return numerator / denominator, True
    else:
        return numerator / denominator, False

results = {}
print("--- Results for n = 11 to n = 20 ---")
for n in range(11, 21):
    value, is_integer = calculate_E(n)
    results[n] = is_integer

    if is_integer:
        print(f"n={n}: INTEGER. Value = {value}")
    else:
        print(f"n={n}: Not an integer.")

# Summarize the findings
integer_solutions = [n for n, is_int in results.items() if is_int]
print("\n--- Summary ---")
print(f"Solutions found in range [11, 20]: {integer_solutions}")

